// L10: the ordinary bridges' table (ordinary.ts, generated by tools/real/bridges.ts).

/** `k` of a railway's row (0: a road). */
export const LINE_KIND_RAIL = 1;

export interface OrdinaryBridgeRow {
  /** 0 road, 1 railway. */
  k: number;
  /** Deck width (m). */
  w: number;
  /** Half-width of the band (m) where the area's roads and railways along the deck are cut. */
  c: number;
  /** The deck's height (game m) at the first and the last point. */
  e: readonly [number, number];
  /** The water's surface under the bridge (game m). */
  l: number;
  /** Rail tracks on the deck (lateral offsets, m; left of the line positive). */
  r?: readonly number[];
  /** The line: x, z pairs in shrunk metres from the strategic grid's north-west corner. */
  p: readonly number[];
}
